import json
def f(g):
    H,W=len(g),len(g[0])
    bg=g[0][0]
    box=[(i,j) for i in range(H) for j in range(W) if g[i][j]!=bg]
    rs=[r for r,c in box]; cs=[c for r,c in box]
    r0,r1=min(rs),max(rs); c0,c1=min(cs),max(cs)
    out=[row[:] for row in g]
    for i in range(r0+1,r1):
        for j in range(c0+1,c1):
            v=g[i][j]
            if v!=bg and v!=g[r0][c0]:
                rr=r1+1 if i==r0 else r0-1
                cc=c1+1 if j==c0 else c0-1
                out[rr][cc]=v
    for i in range(r0+1,r1):
        for j in range(c0+1,c1):
            if g[i][j]!=bg and g[i][j]!=g[r0][c0]:
                out[i][j]=bg
    return out
